// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { SplitPane } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Layout/SplitPane)

figma.connect(SplitPane, FIGMA_NODE_URL, {
  props: {
    label: figma.string('label'),
    orientation: figma.enum('orientation', { 'horizontal': 'horizontal', 'vertical': 'vertical' }),
  },
  example: ({ label, orientation }) => (
    <SplitPane orientation={orientation}>{label}</SplitPane>
  ),
});
